// Decompose a metric change by L1 topic between two periods. Deterministic, no LLM.
const inp = $('Defaults').first().json;

let metric = String(inp.metric || 'csat').toLowerCase().trim();
if (!['csat','volume','resolution_rate'].includes(metric)) metric = 'csat';

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { error: 'no rows', drivers: [] } }];

const N = v => Number(v || 0);
const P = {}, C = {};
for (const r of rows) {
  const bucket = String(r.period) === 'current' ? C : P;
  const k = r.l1_topic;
  if (!bucket[k]) bucket[k] = { sr:0, cs:0, cr:0, rc:0, rr:0 };
  bucket[k].sr += N(r.sr_cnt);  bucket[k].cs += N(r.csat_sum);
  bucket[k].cr += N(r.csat_response_cnt);
  bucket[k].rc += N(r.rsltn_cnt); bucket[k].rr += N(r.rsltn_response_cnt);
}
const keys = [...new Set([...Object.keys(P), ...Object.keys(C)])];
const z = { sr:0, cs:0, cr:0, rc:0, rr:0 };
const roll = o => Object.values(o).reduce((a,b)=>({
  sr:a.sr+b.sr, cs:a.cs+b.cs, cr:a.cr+b.cr, rc:a.rc+b.rc, rr:a.rr+b.rr }), {...z});

const val = t => metric === 'volume' ? t.sr
  : metric === 'csat' ? (t.cr ? t.cs / t.cr : null)
  : (t.rc ? (t.rr / t.rc) * 100 : null);

const pt = roll(P), ct = roll(C);
const totalPrior = val(pt), totalCurrent = val(ct), totalDelta = totalCurrent - totalPrior;

// For CSAT and resolution rate the total is a weighted mean, so a segment's
// contribution is its share of the weighted-sum change, not its own delta.
const drivers = keys.map(k => {
  const p = P[k] || {...z}, c = C[k] || {...z};
  const pv = val(p), cv = val(c);
  let contribution;
  if (metric === 'volume') {
    contribution = c.sr - p.sr;
  } else {
    const w = metric === 'csat' ? 'cr' : 'rc';
    // hold the other segments constant: swap this segment's current values into the prior total
    const swapped = { ...pt };
    swapped.sr = pt.sr - p.sr + c.sr;
    swapped.cs = pt.cs - p.cs + c.cs;  swapped.cr = pt.cr - p.cr + c.cr;
    swapped.rc = pt.rc - p.rc + c.rc;  swapped.rr = pt.rr - p.rr + c.rr;
    contribution = val(swapped) - totalPrior;
    void w;
  }
  return {
    l1_topic: k,
    prior:   pv == null ? null : Number(pv.toFixed(2)),
    current: cv == null ? null : Number(cv.toFixed(2)),
    segment_change: (pv == null || cv == null) ? null : Number((cv - pv).toFixed(2)),
    contribution_to_total: Number(contribution.toFixed(3)),
    share_of_total_change_pct: totalDelta ? Number(((contribution / totalDelta) * 100).toFixed(1)) : null,
    sample_size: metric === 'volume' ? c.sr : (metric === 'csat' ? c.cr : c.rc),
  };
}).sort((a,b) => Math.abs(b.contribution_to_total) - Math.abs(a.contribution_to_total));

// horizontal bar chart of share of total change
const cfg = {
  type: 'horizontalBar',
  data: {
    labels: drivers.map(d => d.l1_topic),
    datasets: [{
      label: 'Share of total change (%)',
      data: drivers.map(d => d.share_of_total_change_pct),
      backgroundColor: drivers.map(d =>
        (d.contribution_to_total < 0) === (totalDelta < 0) ? '#c2410c' : '#1f9d55'),
    }],
  },
  options: {
    title: { display: true, text: `What drove the ${metric} change — ${inp.country === 'ALL' ? 'all countries' : inp.country}` },
    legend: { display: false },
    scales: { xAxes: [{ scaleLabel: { display: true, labelString: '% of total change' } }] },
  },
};
const url = 'https://quickchart.io/chart?w=700&h=320&bkg=white&c=' + encodeURIComponent(JSON.stringify(cfg));

return [{ json: {
  metric,
  scope: inp.country === 'ALL' ? 'all countries' : inp.country,
  prior_period: inp.prior_start + ' to ' + inp.prior_end,
  current_period: inp.current_start + ' to ' + inp.current_end,
  total_prior: totalPrior == null ? null : Number(totalPrior.toFixed(2)),
  total_current: totalCurrent == null ? null : Number(totalCurrent.toFixed(2)),
  total_change: Number(totalDelta.toFixed(2)),
  drivers,
  chart_markdown: `![Contribution by topic](${url})`,
  instruction: 'Copy chart_markdown into your reply verbatim. Report the top drivers by share_of_total_change_pct. Contributions sum to 100% of the total change.',
}}];
